import { defineConfig } from "@tanstack/start/config";
import viteTsConfigPaths from "vite-tsconfig-paths";

export default defineConfig({
  vite: {
    plugins: [
      viteTsConfigPaths({
        projects: ["./tsconfig.json"],
      }),
    ],
  },
});

import { createRouter as createTanStackRouter } from "@tanstack/react-router";
import { routeTree } from "./routeTree.gen";

export function createRouter() {
  const router = createTanStackRouter({
    routeTree,
    scrollRestoration: true,
  });

  return router;
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof createRouter>;
  }
}

import { hydrateRoot } from "react-dom/client";
import { StartClient } from "@tanstack/start";
import { createRouter } from "./router";

const router = createRouter();

hydrateRoot(document, <StartClient router={router} />);

import {
  createStartHandler,
  defaultStreamHandler,
} from "@tanstack/start/server";
import { getRouterManifest } from "@tanstack/start/router-manifest";
import { createRouter } from "./router";

export default createStartHandler({
  createRouter,
  getRouterManifest,
})(defaultStreamHandler);

import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.resolve(process.cwd(), "sqlite.db");

let _db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!_db) {
    _db = new Database(DB_PATH);
    _db.exec(`
      CREATE TABLE IF NOT EXISTS counter (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        value INTEGER NOT NULL DEFAULT 0
      );
      INSERT OR IGNORE INTO counter (id, value) VALUES (1, 0);
    `);
  }
  return _db;
}

import { createServerFn } from "@tanstack/start";
import { getDb } from "../db";

export const getCount = createServerFn({ method: "GET" }).handler(async () => {
  const db = getDb();
  const row = db.prepare("SELECT value FROM counter WHERE id = 1").get() as
    | { value: number }
    | undefined;
  return row?.value ?? 0;
});

export const incrementCount = createServerFn({ method: "POST" }).handler(
  async () => {
    const db = getDb();
    db.prepare(
      "UPDATE counter SET value = value + 1 WHERE id = 1"
    ).run();
    const row = db
      .prepare("SELECT value FROM counter WHERE id = 1")
      .get() as { value: number } | undefined;
    return row?.value ?? 0;
  }
);

import {
  createRootRoute,
  HeadContent,
  Outlet,
  Scripts,
} from "@tanstack/react-router";

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title: "TanStack Start Counter" },
    ],
  }),
  component: RootComponent,
});

function RootComponent() {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        <Outlet />
        <Scripts />
      </body>
    </html>
  );
}

import { createFileRoute, useRouter } from "@tanstack/react-router";
import { useState } from "react";
import { getCount, incrementCount } from "../functions/counter";

export const Route = createFileRoute("/")({
  loader: async () => {
    const count = await getCount();
    return { count };
  },
  component: CounterPage,
});

function CounterPage() {
  const { count: initialCount } = Route.useLoaderData();
  const [count, setCount] = useState(initialCount);
  const router = useRouter();

  const handleIncrement = async () => {
    const newCount = await incrementCount();
    setCount(newCount);
    router.invalidate();
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        fontFamily: "system-ui, sans-serif",
        gap: "1.5rem",
      }}
    >
      <h1 style={{ fontSize: "2rem", margin: 0 }}>TanStack Start Counter</h1>
      <p style={{ fontSize: "1.25rem", margin: 0 }}>
        Count:{" "}
        <strong data-testid="count" style={{ fontSize: "2rem" }}>
          {count}
        </strong>
      </p>
      <button
        data-testid="increment"
        onClick={handleIncrement}
        style={{
          padding: "0.75rem 2rem",
          fontSize: "1rem",
          cursor: "pointer",
          borderRadius: "0.5rem",
          border: "none",
          background: "#3b82f6",
          color: "#fff",
          fontWeight: "bold",
        }}
      >
        Increment
      </button>
    </div>
  );
}

