import initSqlJs, { type Database } from "sql.js";
import fs from "fs";
import path from "path";

const DB_PATH = path.resolve(process.cwd(), "sqlite.db");

let _db: Database | null = null;

async function openDb(): Promise<Database> {
  const SQL = await initSqlJs();
  if (fs.existsSync(DB_PATH)) {
    const buf = fs.readFileSync(DB_PATH);
    return new SQL.Database(buf);
  }
  return new SQL.Database();
}

function saveDb(db: Database) {
  const data = db.export();
  fs.writeFileSync(DB_PATH, Buffer.from(data));
}

export async function getDb(): Promise<Database> {
  if (!_db) {
    _db = await openDb();
    _db.run(`
      CREATE TABLE IF NOT EXISTS counter (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        value INTEGER NOT NULL DEFAULT 0
      );
    `);
    _db.run(`INSERT OR IGNORE INTO counter (id, value) VALUES (1, 0);`);
    saveDb(_db);
  }
  return _db;
}

export { saveDb };

import { createServerFn } from "@tanstack/start";
import { getDb, saveDb } from "../db";

export const getCount = createServerFn({ method: "GET" }).handler(async () => {
  const db = await getDb();
  const result = db.exec("SELECT value FROM counter WHERE id = 1");
  if (result.length === 0 || result[0].values.length === 0) return 0;
  return result[0].values[0][0] as number;
});

export const incrementCount = createServerFn({ method: "POST" }).handler(
  async () => {
    const db = await getDb();
    db.run("UPDATE counter SET value = value + 1 WHERE id = 1");
    saveDb(db);
    const result = db.exec("SELECT value FROM counter WHERE id = 1");
    if (result.length === 0 || result[0].values.length === 0) return 0;
    return result[0].values[0][0] as number;
  }
);
